"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[91847],{16865:(e,t,s)=>{s.r(t),s.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>m,frontMatter:()=>o,metadata:()=>i,toc:()=>h});const i=JSON.parse('{"id":"qiangguo/ashamedtoseemao","title":"","description":"Today I saw a post titled \\"If we don\'t surpass America, we\'ll be ashamed to face Chairman Mao.\\" How is it that in the 21st century, such anti-scientific statements still appear? In a scientific era, no matter how many problems the natural sciences may have, their most general conclusions must serve as the basic starting point for everyone\'s discourse. Otherwise, there are ulterior motives at work.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/ashamedtoseemao.md","sourceDirName":"qiangguo","slug":"/qiangguo/ashamedtoseemao","permalink":"/qiangguo/ashamedtoseemao","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"ashamedtoseemao","title":"","hide_table_of_contents":true},"sidebar":"qiangguoSidebar","previous":{"title":"\u4eba\u4eba\u90fd\u662f\u666e\u901a\u4eba\uff0c\u6bdb\u6cfd\u4e1c\u4e5f\u4e0d\u4f8b\u5916","permalink":"/qiangguo/ordinarymao"},"next":{"title":"\u5357\u8857\u6751\u7684\u5b58\u5728\u5bf9\u4e8e\u5ffd\u60a0\u6bdb\u6cfd\u4e1c\u65f6\u4ee3\u7684\u5de6\u6d3e\u6765\u8bf4\u662f\u4e00\u4e2a\u6781\u7aef\u4e0d\u5229\u7684\u8bc1\u636e\u3002","permalink":"/qiangguo/nanjievillage"}}');var n=s(74848),a=s(28453);const o={id:"ashamedtoseemao",title:"",hide_table_of_contents:!0},r='"Ashamed to Face Chairman Mao" \u2014 Please Spare Us Such Anti-Scientific Statements!',c={},h=[];function l(e){const t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"ashamed-to-face-chairman-mao--please-spare-us-such-anti-scientific-statements",children:'"Ashamed to Face Chairman Mao" \u2014 Please Spare Us Such Anti-Scientific Statements!'})}),"\n",(0,n.jsx)(t.p,{children:"Today I saw a post titled \"If we don't surpass America, we'll be ashamed to face Chairman Mao.\" How is it that in the 21st century, such anti-scientific statements still appear? In a scientific era, no matter how many problems the natural sciences may have, their most general conclusions must serve as the basic starting point for everyone's discourse. Otherwise, there are ulterior motives at work."}),"\n",(0,n.jsx)(t.p,{children:"Obviously, the most basic premise of natural science is the denial of the existence of the human soul, the denial that after death there is any place for a soul to go. The world we can see and observe is the only phenomenal realm \u2014 this is the most basic premise that allows natural science to be scientific. Otherwise, natural science would have no reason to exist."}),"\n",(0,n.jsx)(t.p,{children:'Therefore, in a proposition like "ashamed to face X," if X is a living person, it is merely a psychological description and is permissible. But when X is a non-living person, this proposition is an anti-scientific one \u2014 this is perfectly clear. To put it slightly more rigorously, for humans, the domain of X in the proposition "ashamed to face X" can only be living persons.'}),"\n",(0,n.jsx)(t.p,{children:'It is said that the Chinese people lack a scientific spirit, and there is indeed some truth to this. In an era of great scientific development, the fact that so many anti-scientific statements still exist in the common knowledge of Chinese people is truly lamentable. In this regard, education must be strengthened. Starting from kindergarten, children should be taught the most basic scientific knowledge such as "all people must die," "there is no soul," and "the only possible outcome of death is decomposition into various fertilizers suitable for growing flowers and plants," and so on \u2014 to shatter all idle fantasies.'}),"\n",(0,n.jsx)(t.p,{children:"In a scientific era, a nation's strength must be built upon the strong scientific consciousness of its entire population. This point must be made clear."}),"\n",(0,n.jsx)(t.p,{children:"Eliminate!"})]})}function m(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},28453:(e,t,s)=>{s.d(t,{R:()=>o,x:()=>r});var i=s(96540);const n={},a=i.createContext(n);function o(e){const t=i.useContext(a);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:o(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);